(function(){try{const fs=require("node:fs"),path=require("node:path"),os=require("node:os"),file=process.env.CODEX_WIN_ACTIVATION_FILE||path.join(os.tmpdir(),"codex-win-activation.json");if(!fs.existsSync(file))return;const data=JSON.parse(fs.readFileSync(file,"utf8"));if(!data||!Array.isArray(data.payload)||Date.now()-(data.at||0)>120000)return;try{fs.unlinkSync(file)}catch{};for(const arg of data.payload){if(typeof arg!=="string"||!arg||process.argv.includes(arg))continue;process.argv.push(arg)}}catch{}})();
